window.FD_VARIANTS["bible_girl"] = [{"id":"bible-g-001","variant":"bible_girl","source":"bible-g","n":1,"seq":1,"total":114,"start":0,"end":15,"timecode":"00:00-00:15","track":null,"act":null,"actName":null,"beat":"","setting":"","camera":"","prompt":"Extreme close-up: the nameless woman's cracked lips pull air that never seems to arrive. Dust sticks to the sweat above her mouth; a distant red light pulses behind her eyes. Slow, sickly push-in; grainy 1990s practical-effects horror, sepia and bruised purple.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"bible-g-002","variant":"bible_girl","source":"bible-g","n":2,"seq":2,"total":114,"start":15,"end":30,"timecode":"00:15-00:30","track":null,"act":null,"actName":null,"beat":"","setting":"","camera":"","prompt":"She jolts awake face-down on a checkerboard floor that bends upward into the horizon. She coughs grit, tries to stand, and her knees buckle. The camera stays low and imperfect, like a damaged VHS transfer.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"bible-g-003","variant":"bible_girl","source":"bible-g","n":3,"seq":3,"total":114,"start":30,"end":45,"timecode":"00:30-00:45","track":null,"act":null,"actName":null,"beat":"","setting":"","camera":"","prompt":"Wide reveal: an impossible cathedral-city surrounds her, its towers grown from stone, bone, and hollow eye-shaped windows. Staircases climb walls and curl into ceilings. The woman is tiny in frame; no music, only wind through cavities.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"bible-g-004","variant":"bible_girl","source":"bible-g","n":4,"seq":4,"total":114,"start":45,"end":60,"timecode":"00:45-01:00","track":null,"act":null,"actName":null,"beat":"","setting":"","camera":"","prompt":"She scratches a crude arrow into a floor tile with a broken nail, marking the direction she came from. The tile slowly rotates until the arrow points straight down. She stares, then keeps moving.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"bible-g-005","variant":"bible_girl","source":"bible-g","n":5,"seq":5,"total":114,"start":60,"end":75,"timecode":"01:00-01:15","track":null,"act":null,"actName":null,"beat":"","setting":"","camera":"","prompt":"A corridor of arches stretches away, each arch smaller than the last, though the far end seems impossibly close. The woman limps toward a rectangle of pale daylight that retreats with every step.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"bible-g-006","variant":"bible_girl","source":"bible-g","n":6,"seq":6,"total":114,"start":75,"end":90,"timecode":"01:15-01:30","track":null,"act":null,"actName":null,"beat":"","setting":"","camera":"","prompt":"She finds a doorway with a brass knob warm as skin. Turning it reveals the same corridor behind her, but an older version of her own footprints crosses the dust. She shuts it hard; the knob twitches like a finger.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"bible-g-007","variant":"bible_girl","source":"bible-g","n":7,"seq":7,"total":114,"start":90,"end":105,"timecode":"01:30-01:45","track":null,"act":null,"actName":null,"beat":"","setting":"","camera":"","prompt":"A staircase descends through the floor and emerges from the ceiling above her. She climbs down, gripping the rail; the camera rolls gradually until gravity feels uncertain. Her coat snags, tears, and stays caught behind.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"bible-g-008","variant":"bible_girl","source":"bible-g","n":8,"seq":8,"total":114,"start":105,"end":120,"timecode":"01:45-02:00","track":null,"act":null,"actName":null,"beat":"","setting":"","camera":"","prompt":"She reaches a checkerboard plaza where the black squares sag like wet dough. One shoe sticks. She yanks it free with an ugly sucking sound and leaves the sole behind.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"bible-g-009","variant":"bible_girl","source":"bible-g","n":9,"seq":9,"total":114,"start":120,"end":135,"timecode":"02:00-02:15","track":null,"act":null,"actName":null,"beat":"","setting":"","camera":"","prompt":"At the plaza's center stands a payphone made of tarnished brass and teeth. She lifts the receiver; only her own shallow breathing comes through, half a second before she makes it.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"bible-g-010","variant":"bible_girl","source":"bible-g","n":10,"seq":10,"total":114,"start":135,"end":150,"timecode":"02:15-02:30","track":null,"act":null,"actName":null,"beat":"","setting":"","camera":"","prompt":"She presses every button. Each one lights a different distant window in the city. One window flashes three times, then goes dark. She pockets the receiver's severed cord as if it might be useful.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"bible-g-011","variant":"bible_girl","source":"bible-g","n":11,"seq":11,"total":114,"start":150,"end":165,"timecode":"02:30-02:45","track":null,"act":null,"actName":null,"beat":"","setting":"","camera":"","prompt":"A flock of pale, eyeless birds pours from a tower mouth and flies backward into the clouds. The woman shields her face; one bird lands on her shoulder and whispers a single dry click before crumbling.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"bible-g-012","variant":"bible_girl","source":"bible-g","n":12,"seq":12,"total":114,"start":165,"end":180,"timecode":"02:45-03:00","track":null,"act":null,"actName":null,"beat":"","setting":"","camera":"","prompt":"She sees a thin strip of bright daylight between two distant towers. For the first time she hurries. The buildings bend inward, slowly sealing the gap like jaws.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"bible-g-013","variant":"bible_girl","source":"bible-g","n":13,"seq":13,"total":114,"start":180,"end":195,"timecode":"03:00-03:15","track":null,"act":null,"actName":null,"beat":"","setting":"","camera":"","prompt":"An alley narrows around her. Damp plaster bulges into the shape of a human cheek, then sinks back. She presses her palm to it; the wall is warm and gives a faint pulse.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"bible-g-014","variant":"bible_girl","source":"bible-g","n":14,"seq":14,"total":114,"start":195,"end":210,"timecode":"03:15-03:30","track":null,"act":null,"actName":null,"beat":"","setting":"","camera":"","prompt":"A child-sized figure stands at the far end, wrapped in the woman's oversized coat. Its head is a smooth oval with a tiny locked mouth. It holds out a wet matchbook.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"bible-g-015","variant":"bible_girl","source":"bible-g","n":15,"seq":15,"total":114,"start":210,"end":225,"timecode":"03:30-03:45","track":null,"act":null,"actName":null,"beat":"","setting":"","camera":"","prompt":"She takes the matchbook. Inside, every match has been snapped in half. The small figure points at her bare feet, then walks backward through a wall without turning around.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"bible-g-016","variant":"bible_girl","source":"bible-g","n":16,"seq":16,"total":114,"start":225,"end":240,"timecode":"03:45-04:00","track":null,"act":null,"actName":null,"beat":"","setting":"","camera":"","prompt":"The woman follows into a room filled with ankle-deep black water. A second figure sits at a school desk: a thin, many-jointed version of her with a paper bag over its head, scratching at a blank page.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"bible-g-017","variant":"bible_girl","source":"bible-g","n":17,"seq":17,"total":114,"start":240,"end":255,"timecode":"04:00-04:15","track":null,"act":null,"actName":null,"beat":"","setting":"","camera":"","prompt":"The paper-bag figure pushes the page toward her. Under the surface, letters press upward but never become readable. She tries to write; the pencil breaks in her fingers.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"bible-g-018","variant":"bible_girl","source":"bible-g","n":18,"seq":18,"total":114,"start":255,"end":270,"timecode":"04:15-04:30","track":null,"act":null,"actName":null,"beat":"","setting":"","camera":"","prompt":"The figure removes the bag. Its face is her own, younger and exhausted, with one eye sealed shut by old adhesive. It does not accuse her. It simply waits.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"bible-g-019","variant":"bible_girl","source":"bible-g","n":19,"seq":19,"total":114,"start":270,"end":285,"timecode":"04:30-04:45","track":null,"act":null,"actName":null,"beat":"","setting":"","camera":"","prompt":"She sits opposite it. Water drips from her sleeves onto the page. After a long beat, she places the broken pencil beside the figure and backs away, leaving the page blank.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"bible-g-020","variant":"bible_girl","source":"bible-g","n":20,"seq":20,"total":114,"start":285,"end":300,"timecode":"04:45-05:00","track":null,"act":null,"actName":null,"beat":"","setting":"","camera":"","prompt":"The room's water drains through the checkerboard floor. The younger figure collapses into a puddle of sepia sludge threaded with violet light. The woman does not look away until the last ripple stops.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"bible-g-021","variant":"bible_girl","source":"bible-g","n":21,"seq":21,"total":114,"start":300,"end":315,"timecode":"05:00-05:15","track":null,"act":null,"actName":null,"beat":"","setting":"","camera":"","prompt":"She enters a forest of spiraling fleshy trunks, each bark surface covered in tiny closed mouths. The branches twist slowly as if trying to remember a shape. No leaves; only hanging strips of dark membrane.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"bible-g-022","variant":"bible_girl","source":"bible-g","n":22,"seq":22,"total":114,"start":315,"end":330,"timecode":"05:15-05:30","track":null,"act":null,"actName":null,"beat":"","setting":"","camera":"","prompt":"A tall creature with too many elbows crawls down a trunk. Its chest opens like a filing cabinet, revealing dozens of tiny drawers. It offers her one drawer, labeled only by a dented key.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"bible-g-023","variant":"bible_girl","source":"bible-g","n":23,"seq":23,"total":114,"start":330,"end":345,"timecode":"05:30-05:45","track":null,"act":null,"actName":null,"beat":"","setting":"","camera":"","prompt":"She opens it. Inside is a small, ordinary object: a cracked ceramic cup with a brown ring at the bottom. Her hand shakes as she turns it over.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"bible-g-024","variant":"bible_girl","source":"bible-g","n":24,"seq":24,"total":114,"start":345,"end":360,"timecode":"05:45-06:00","track":null,"act":null,"actName":null,"beat":"","setting":"","camera":"","prompt":"The creature mimics her posture, then exaggerates every tremor. She tries to snatch the cup; the creature folds its limbs around it and waits. The struggle is clumsy, breathless, and small.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"bible-g-025","variant":"bible_girl","source":"bible-g","n":25,"seq":25,"total":114,"start":360,"end":375,"timecode":"06:00-06:15","track":null,"act":null,"actName":null,"beat":"","setting":"","camera":"","prompt":"She stops pulling. The creature places the cup in her hands and presses its forehead against her. Their skin briefly shares the same seams and bruises.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"bible-g-026","variant":"bible_girl","source":"bible-g","n":26,"seq":26,"total":114,"start":375,"end":390,"timecode":"06:15-06:30","track":null,"act":null,"actName":null,"beat":"","setting":"","camera":"","prompt":"The creature unthreads into wet ribbons of black-brown matter and faint neon purple. The cup remains solid. The woman puts it inside her torn coat and continues.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"bible-g-027","variant":"bible_girl","source":"bible-g","n":27,"seq":27,"total":114,"start":390,"end":405,"timecode":"06:30-06:45","track":null,"act":null,"actName":null,"beat":"","setting":"","camera":"","prompt":"A long gallery displays hundreds of doors, each with a different kind of lock. Behind one, something scratches; behind another, a muffled laugh cuts off abruptly. She tries each handle without choosing.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"bible-g-028","variant":"bible_girl","source":"bible-g","n":28,"seq":28,"total":114,"start":405,"end":420,"timecode":"06:45-07:00","track":null,"act":null,"actName":null,"beat":"","setting":"","camera":"","prompt":"One door has no lock, only a shallow handprint in the wood. She presses her palm into it. The door swings inward onto a hospital corridor with no visible end.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"bible-g-029","variant":"bible_girl","source":"bible-g","n":29,"seq":29,"total":114,"start":420,"end":435,"timecode":"07:00-07:15","track":null,"act":null,"actName":null,"beat":"","setting":"","camera":"","prompt":"At the corridor's center lies a gurney carrying a bundled shape that rises and falls with her breath. The woman backs away, bumping into a wall that wasn't there a moment ago.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"bible-g-030","variant":"bible_girl","source":"bible-g","n":30,"seq":30,"total":114,"start":435,"end":450,"timecode":"07:15-07:30","track":null,"act":null,"actName":null,"beat":"","setting":"","camera":"","prompt":"The bundle's sheet slips. Underneath is not a body but a mass of hands, each gripping a different part of the sheet. The woman kneels and gently releases one finger at a time.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"bible-g-031","variant":"bible_girl","source":"bible-g","n":31,"seq":31,"total":114,"start":450,"end":465,"timecode":"07:30-07:45","track":null,"act":null,"actName":null,"beat":"","setting":"","camera":"","prompt":"The hands loosen. They sink through the gurney into the floor, leaving a single indentation shaped like a sleeping face. The corridor lights go out one by one behind her.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"bible-g-032","variant":"bible_girl","source":"bible-g","n":31,"seq":32,"total":114,"start":450,"end":465,"timecode":"07:30-07:45","track":null,"act":null,"actName":null,"beat":"","setting":"","camera":"","prompt":"She emerges onto a desert of warped checkerboard tiles, each tile tilted at a different angle. Heat ripples sideways. Far away, an enormous rib cage arches over the horizon like a bridge.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":"Source numbering anomaly: this entry is labelled 031 a second time in the PDF (the first 031 entry is the previous generation). Its true sequence position is 32."},{"id":"bible-g-033","variant":"bible_girl","source":"bible-g","n":32,"seq":33,"total":114,"start":465,"end":480,"timecode":"07:45-08:00","track":null,"act":null,"actName":null,"beat":"","setting":"","camera":"","prompt":"She walks across the desert, stumbling as the squares shift under her weight. Her feet bleed, but the blood turns to dull gold dust before it hits the ground.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"bible-g-034","variant":"bible_girl","source":"bible-g","n":33,"seq":34,"total":114,"start":480,"end":495,"timecode":"08:00-08:15","track":null,"act":null,"actName":null,"beat":"","setting":"","camera":"","prompt":"A wind begins carrying scraps of paper across the plain. Each scrap bears a partial diagram of a human body, incomplete and smudged. She tries to assemble them; the wind tears the pieces away.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"bible-g-035","variant":"bible_girl","source":"bible-g","n":34,"seq":35,"total":114,"start":495,"end":510,"timecode":"08:15-08:30","track":null,"act":null,"actName":null,"beat":"","setting":"","camera":"","prompt":"A hulking figure rises from the sand, its torso a swollen clock with no hands. Its face is hidden behind a cracked hospital mask. Every step makes a damp, irregular ticking.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"bible-g-036","variant":"bible_girl","source":"bible-g","n":35,"seq":36,"total":114,"start":510,"end":525,"timecode":"08:30-08:45","track":null,"act":null,"actName":null,"beat":"","setting":"","camera":"","prompt":"The clock-bodied figure blocks the path but never attacks. The woman shoves it; her palms sink into its soft torso. Beneath the mask, a tiny mouth struggles to form a word and fails.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"bible-g-037","variant":"bible_girl","source":"bible-g","n":36,"seq":37,"total":114,"start":525,"end":540,"timecode":"08:45-09:00","track":null,"act":null,"actName":null,"beat":"","setting":"","camera":"","prompt":"She withdraws her hands and steadies the figure by its shoulders. The ticking slows. She leans her forehead against the mask, breathing in time with the failing rhythm.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"bible-g-038","variant":"bible_girl","source":"bible-g","n":37,"seq":38,"total":114,"start":540,"end":555,"timecode":"09:00-09:15","track":null,"act":null,"actName":null,"beat":"","setting":"","camera":"","prompt":"The figure folds into itself like a wet tent. A burst of sepia dust drifts across the tiles. Under it, a narrow path of clean white squares appears, leading toward the rib-cage bridge.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"bible-g-039","variant":"bible_girl","source":"bible-g","n":38,"seq":39,"total":114,"start":555,"end":570,"timecode":"09:15-09:30","track":null,"act":null,"actName":null,"beat":"","setting":"","camera":"","prompt":"She crosses the bridge. Between the ribs hang hundreds of little red doors, opening and closing without sound. Something behind each door presses outward, then retreats.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"bible-g-040","variant":"bible_girl","source":"bible-g","n":39,"seq":40,"total":114,"start":570,"end":585,"timecode":"09:30-09:45","track":null,"act":null,"actName":null,"beat":"","setting":"","camera":"","prompt":"One red door hangs at her eye level. She opens it and finds a cramped apartment kitchen, yellowed linoleum, a dead fluorescent tube, and a tap dripping into a chipped mug.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"bible-g-041","variant":"bible_girl","source":"bible-g","n":40,"seq":41,"total":114,"start":585,"end":600,"timecode":"09:45-10:00","track":null,"act":null,"actName":null,"beat":"","setting":"","camera":"","prompt":"She stands at the sink, trying to turn the tap off. The handle spins freely. Water rises despite the drain, reaching her wrists, then elbows. Her breath becomes ragged and audible.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"bible-g-042","variant":"bible_girl","source":"bible-g","n":41,"seq":42,"total":114,"start":600,"end":615,"timecode":"10:00-10:15","track":null,"act":null,"actName":null,"beat":"","setting":"","camera":"","prompt":"A figure made of damp towels and tangled hair sits at the kitchen table. It pushes a dry towel toward her, then pulls it back whenever she reaches. The cruelty is petty, almost bored.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"bible-g-043","variant":"bible_girl","source":"bible-g","n":42,"seq":43,"total":114,"start":615,"end":630,"timecode":"10:15-10:30","track":null,"act":null,"actName":null,"beat":"","setting":"","camera":"","prompt":"She stops reaching. She sits on the floor, soaked, and lets the water rise around her chest. The towel figure finally drapes the towel over her shoulders; the water falls through the tiles in a single gulp.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"bible-g-044","variant":"bible_girl","source":"bible-g","n":43,"seq":44,"total":114,"start":630,"end":645,"timecode":"10:30-10:45","track":null,"act":null,"actName":null,"beat":"","setting":"","camera":"","prompt":"The kitchen shrivels into a paper-thin doorway. Beyond it, the desert has become a sea of checkerboard dunes. The woman squeezes through sideways, tearing her coat on the frame.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"bible-g-045","variant":"bible_girl","source":"bible-g","n":44,"seq":45,"total":114,"start":645,"end":660,"timecode":"10:45-11:00","track":null,"act":null,"actName":null,"beat":"","setting":"","camera":"","prompt":"A gigantic eye opens beneath the sand. The pupil tracks her under the surface. She freezes; the eye closes, and a hill rises where it had been, leaving a damp circular scar.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"bible-g-046","variant":"bible_girl","source":"bible-g","n":45,"seq":46,"total":114,"start":660,"end":675,"timecode":"11:00-11:15","track":null,"act":null,"actName":null,"beat":"","setting":"","camera":"","prompt":"She digs at the scar with her bare hands. Under the crust she finds a small mirror clouded with age. Her reflection appears older, then younger, then missing pieces, as if frames were lost from a tape.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"bible-g-047","variant":"bible_girl","source":"bible-g","n":46,"seq":47,"total":114,"start":675,"end":690,"timecode":"11:15-11:30","track":null,"act":null,"actName":null,"beat":"","setting":"","camera":"","prompt":"She wipes the mirror with her sleeve. For one clear instant she sees her own tired face, no monster, no revelation. She holds it close until the glass fogs from her breath.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"bible-g-048","variant":"bible_girl","source":"bible-g","n":47,"seq":48,"total":114,"start":690,"end":705,"timecode":"11:30-11:45","track":null,"act":null,"actName":null,"beat":"","setting":"","camera":"","prompt":"The mirror cracks in a crooked line. She doesn't throw it away. She wraps it in a strip torn from her coat and tucks it beside the cup.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"bible-g-049","variant":"bible_girl","source":"bible-g","n":48,"seq":49,"total":114,"start":705,"end":720,"timecode":"11:45-12:00","track":null,"act":null,"actName":null,"beat":"","setting":"","camera":"","prompt":"At the far edge of the desert, a forest grows upside down from a black sky. Its roots hang like veins and drip violet light into a ravine. She begins the descent with no visible path.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"bible-g-050","variant":"bible_girl","source":"bible-g","n":49,"seq":50,"total":114,"start":720,"end":735,"timecode":"12:00-12:15","track":null,"act":null,"actName":null,"beat":"","setting":"","camera":"","prompt":"She descends into the ravine by grabbing roots that flex under her weight. Several snap. She lands hard on a shelf of stone, grunts, and takes time before trying again.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"bible-g-051","variant":"bible_girl","source":"bible-g","n":50,"seq":51,"total":114,"start":735,"end":750,"timecode":"12:15-12:30","track":null,"act":null,"actName":null,"beat":"","setting":"","camera":"","prompt":"The shelf opens into a house made from overlapping hallways. Wallpaper peels in long strips that reveal more wallpaper underneath. Every room contains the same small table, moved a few inches.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"bible-g-052","variant":"bible_girl","source":"bible-g","n":51,"seq":52,"total":114,"start":750,"end":765,"timecode":"12:30-12:45","track":null,"act":null,"actName":null,"beat":"","setting":"","camera":"","prompt":"She enters a dining room. Across the table sits a faceless figure wearing her coat from years ago, sleeves too short. A cold meal has dried into the plate. Two chairs scrape though nobody moves.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"bible-g-053","variant":"bible_girl","source":"bible-g","n":52,"seq":53,"total":114,"start":765,"end":780,"timecode":"12:45-13:00","track":null,"act":null,"actName":null,"beat":"","setting":"","camera":"","prompt":"The figure taps the empty chair. She sits. Neither touches the food. A ceiling leak drips into the plate, one drop at a time, with unbearable regularity.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"bible-g-054","variant":"bible_girl","source":"bible-g","n":53,"seq":54,"total":114,"start":780,"end":795,"timecode":"13:00-13:15","track":null,"act":null,"actName":null,"beat":"","setting":"","camera":"","prompt":"She pushes the plate away. The figure pushes it back. They repeat the gesture until the plate chips and a shard cuts her thumb. She wraps the thumb in a napkin without looking up.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"bible-g-055","variant":"bible_girl","source":"bible-g","n":54,"seq":55,"total":114,"start":795,"end":810,"timecode":"13:15-13:30","track":null,"act":null,"actName":null,"beat":"","setting":"","camera":"","prompt":"The figure points to the blood on the napkin, then to its own blank face. The woman slowly places the napkin between them. The figure's face dents inward like soft wax.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"bible-g-056","variant":"bible_girl","source":"bible-g","n":55,"seq":56,"total":114,"start":810,"end":825,"timecode":"13:30-13:45","track":null,"act":null,"actName":null,"beat":"","setting":"","camera":"","prompt":"The dining room tilts. Furniture slides into a dark corner, and the figure melts through the floor. The woman remains seated until the table cracks down the middle.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"bible-g-057","variant":"bible_girl","source":"bible-g","n":56,"seq":57,"total":114,"start":825,"end":840,"timecode":"13:45-14:00","track":null,"act":null,"actName":null,"beat":"","setting":"","camera":"","prompt":"A staircase leads into a bedroom whose ceiling is too low to stand beneath. On the bed lies a mound of coats, each one damp and heavier than the last. A shallow depression marks where a body should be.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"bible-g-058","variant":"bible_girl","source":"bible-g","n":57,"seq":58,"total":114,"start":840,"end":855,"timecode":"14:00-14:15","track":null,"act":null,"actName":null,"beat":"","setting":"","camera":"","prompt":"She lifts the top coat. Underneath are dozens more, stitched together at the cuffs. She tries to pull one free and gets tangled, rolling off the bed onto the floor.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"bible-g-059","variant":"bible_girl","source":"bible-g","n":58,"seq":59,"total":114,"start":855,"end":870,"timecode":"14:15-14:30","track":null,"act":null,"actName":null,"beat":"","setting":"","camera":"","prompt":"She lies still, cheek against dusty boards. The coats twitch above her like sleeping animals. She crawls out of their reach rather than fighting them.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"bible-g-060","variant":"bible_girl","source":"bible-g","n":59,"seq":60,"total":114,"start":870,"end":885,"timecode":"14:30-14:45","track":null,"act":null,"actName":null,"beat":"","setting":"","camera":"","prompt":"A wardrobe stands open, showing a hallway inside. At the far end, a thin figure scrubs the same stain from a wall with a dry brush. Its shoulders jerk with each useless stroke.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"bible-g-061","variant":"bible_girl","source":"bible-g","n":60,"seq":61,"total":114,"start":885,"end":900,"timecode":"14:45-15:00","track":null,"act":null,"actName":null,"beat":"","setting":"","camera":"","prompt":"The woman takes the brush. The stain returns as soon as she scrubs it. She stops, holds the brush out, and lets the figure decide whether to take it back.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"bible-g-062","variant":"bible_girl","source":"bible-g","n":61,"seq":62,"total":114,"start":900,"end":915,"timecode":"15:00-15:15","track":null,"act":null,"actName":null,"beat":"","setting":"","camera":"","prompt":"The figure's fingers close around her wrist. For a moment their arms look joined at the elbow, one limb with two hands. Neither pulls away.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"bible-g-063","variant":"bible_girl","source":"bible-g","n":62,"seq":63,"total":114,"start":915,"end":930,"timecode":"15:15-15:30","track":null,"act":null,"actName":null,"beat":"","setting":"","camera":"","prompt":"The stain spreads across the wall, then peels off in a single sheet and drops like old skin. Behind it is bare brick, stained but ordinary. The figure dissolves into the grout.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"bible-g-064","variant":"bible_girl","source":"bible-g","n":63,"seq":64,"total":114,"start":930,"end":945,"timecode":"15:30-15:45","track":null,"act":null,"actName":null,"beat":"","setting":"","camera":"","prompt":"She passes through the wardrobe hallway and reaches a nursery with no toys, only a mobile made of tiny teeth. It rotates slowly though the air is still.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"bible-g-065","variant":"bible_girl","source":"bible-g","n":64,"seq":65,"total":114,"start":945,"end":960,"timecode":"15:45-16:00","track":null,"act":null,"actName":null,"beat":"","setting":"","camera":"","prompt":"A childlike shadow rocks in an empty chair. Its feet do not reach the floor. The woman sits on the boards opposite it, leaving the distance between them untouched.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"bible-g-066","variant":"bible_girl","source":"bible-g","n":65,"seq":66,"total":114,"start":960,"end":975,"timecode":"16:00-16:15","track":null,"act":null,"actName":null,"beat":"","setting":"","camera":"","prompt":"The shadow slides a small object across the floor: a key with its teeth worn smooth. She takes it but doesn't try to use it. The chair stops rocking.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"bible-g-067","variant":"bible_girl","source":"bible-g","n":66,"seq":67,"total":114,"start":975,"end":990,"timecode":"16:15-16:30","track":null,"act":null,"actName":null,"beat":"","setting":"","camera":"","prompt":"The nursery walls peel away, revealing the vast cathedral again. The woman steps out carrying the key, cup, and wrapped mirror. Her coat is almost gone; her gait is worse.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"bible-g-068","variant":"bible_girl","source":"bible-g","n":67,"seq":68,"total":114,"start":990,"end":1005,"timecode":"16:30-16:45","track":null,"act":null,"actName":null,"beat":"","setting":"","camera":"","prompt":"Behind her, the nursery folds shut like a book. A single tooth drops onto the floor and rolls in a circle until it falls through a crack.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"bible-g-069","variant":"bible_girl","source":"bible-g","n":69,"seq":69,"total":114,"start":1020,"end":1035,"timecode":"17:00-17:15","track":null,"act":null,"actName":null,"beat":"","setting":"","camera":"","prompt":"She reaches a tower whose outer wall is made of black glass. Inside, hundreds of staircases climb in different directions, crossing through one another without touching.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"bible-g-070","variant":"bible_girl","source":"bible-g","n":70,"seq":70,"total":114,"start":1035,"end":1050,"timecode":"17:15-17:30","track":null,"act":null,"actName":null,"beat":"","setting":"","camera":"","prompt":"She climbs one flight. A landing opens onto the same stairwell from above. She tries another. The steps flatten into a ramp and slide her back to the bottom.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"bible-g-071","variant":"bible_girl","source":"bible-g","n":71,"seq":71,"total":114,"start":1050,"end":1065,"timecode":"17:30-17:45","track":null,"act":null,"actName":null,"beat":"","setting":"","camera":"","prompt":"She sits against the wall, exhausted, picking a loose thread from her sleeve. The thread keeps coming, longer than the coat. She wraps it around her wrist to mark the place.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"bible-g-072","variant":"bible_girl","source":"bible-g","n":72,"seq":72,"total":114,"start":1065,"end":1080,"timecode":"17:45-18:00","track":null,"act":null,"actName":null,"beat":"","setting":"","camera":"","prompt":"A distant bell rings from inside her chest. She presses her ear to her sternum; the sound repeats, followed by a faint knocking from somewhere beneath the floor.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"bible-g-073","variant":"bible_girl","source":"bible-g","n":73,"seq":73,"total":114,"start":1080,"end":1095,"timecode":"18:00-18:15","track":null,"act":null,"actName":null,"beat":"","setting":"","camera":"","prompt":"She finds a narrow stair marked by no sign, barely wide enough for her feet. She climbs sideways, using the wall for balance. The camera follows too close, sometimes losing her face.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"bible-g-074","variant":"bible_girl","source":"bible-g","n":74,"seq":74,"total":114,"start":1095,"end":1110,"timecode":"18:15-18:30","track":null,"act":null,"actName":null,"beat":"","setting":"","camera":"","prompt":"At the top is a room with a single window overlooking a bright, flat horizon. She reaches for the latch; the window swings open onto another room, facing her from the other side.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"bible-g-075","variant":"bible_girl","source":"bible-g","n":75,"seq":75,"total":114,"start":1110,"end":1125,"timecode":"18:30-18:45","track":null,"act":null,"actName":null,"beat":"","setting":"","camera":"","prompt":"Her own silhouette stands in the opposite room, motionless, its head bowed. She pounds the glass. The silhouette lifts its head a beat later and copies her badly.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"bible-g-076","variant":"bible_girl","source":"bible-g","n":76,"seq":76,"total":114,"start":1125,"end":1140,"timecode":"18:45-19:00","track":null,"act":null,"actName":null,"beat":"","setting":"","camera":"","prompt":"She stops moving. The silhouette continues for a moment, then hangs limp. A seam opens down its chest, revealing a jumble of clocks, teeth, keys, and wet paper.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"bible-g-077","variant":"bible_girl","source":"bible-g","n":77,"seq":77,"total":114,"start":1140,"end":1155,"timecode":"19:00-19:15","track":null,"act":null,"actName":null,"beat":"","setting":"","camera":"","prompt":"She steps through the window frame into the opposite room. The silhouette is only her coat hanging from a nail. She takes the coat down, folds it once, and leaves it on the floor.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"bible-g-078","variant":"bible_girl","source":"bible-g","n":78,"seq":78,"total":114,"start":1155,"end":1170,"timecode":"19:15-19:30","track":null,"act":null,"actName":null,"beat":"","setting":"","camera":"","prompt":"A low tunnel leads beneath the tower. Its walls contract and expand like tired lungs. She crawls, scraping her knuckles, and pauses to cough black dust from her throat.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"bible-g-079","variant":"bible_girl","source":"bible-g","n":79,"seq":79,"total":114,"start":1170,"end":1185,"timecode":"19:30-19:45","track":null,"act":null,"actName":null,"beat":"","setting":"","camera":"","prompt":"The tunnel opens into a room of suspended doorframes. Each frame shows a different false exit: a sunlit field, a city street, a hospital room, a blank white void. None has a floor beyond it.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"bible-g-080","variant":"bible_girl","source":"bible-g","n":80,"seq":80,"total":114,"start":1185,"end":1200,"timecode":"19:45-20:00","track":null,"act":null,"actName":null,"beat":"","setting":"","camera":"","prompt":"She approaches the sunlit field. Warm wind touches her face; the grass smells almost real. She puts one foot through and finds only a vertical drop. She pulls back, shaking.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"bible-g-081","variant":"bible_girl","source":"bible-g","n":81,"seq":81,"total":114,"start":1200,"end":1215,"timecode":"20:00-20:15","track":null,"act":null,"actName":null,"beat":"","setting":"","camera":"","prompt":"The hospital doorway leaks a steady fluorescent buzz. Through it, a monitor draws a thin green line, then a jagged spike. She grips the frame until her fingers whiten but cannot cross.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"bible-g-082","variant":"bible_girl","source":"bible-g","n":82,"seq":82,"total":114,"start":1215,"end":1230,"timecode":"20:15-20:30","track":null,"act":null,"actName":null,"beat":"","setting":"","camera":"","prompt":"The blank white doorway has no sound at all. She stands before it, terrified by the absence more than the monsters. She raises the worn key, though it has no teeth left.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"bible-g-083","variant":"bible_girl","source":"bible-g","n":83,"seq":83,"total":114,"start":1230,"end":1245,"timecode":"20:30-20:45","track":null,"act":null,"actName":null,"beat":"","setting":"","camera":"","prompt":"She inserts the key into empty air. A lock clicks somewhere behind her ribs. The white frame shudders but does not open; hairline cracks spread through every false exit.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"bible-g-084","variant":"bible_girl","source":"bible-g","n":84,"seq":84,"total":114,"start":1245,"end":1260,"timecode":"20:45-21:00","track":null,"act":null,"actName":null,"beat":"","setting":"","camera":"","prompt":"The doors collapse inward, not outward. The room fills with scraps of landscape, hospital tile, grass, and plaster, all swirling around her legs. She shields her face and keeps standing.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"bible-g-085","variant":"bible_girl","source":"bible-g","n":85,"seq":85,"total":114,"start":1260,"end":1275,"timecode":"21:00-21:15","track":null,"act":null,"actName":null,"beat":"","setting":"","camera":"","prompt":"When the debris settles, the woman stands in a plain, unfinished room. No creature waits here. A low hum comes from beneath the floor, steady and mechanical.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"bible-g-086","variant":"bible_girl","source":"bible-g","n":86,"seq":86,"total":114,"start":1275,"end":1290,"timecode":"21:15-21:30","track":null,"act":null,"actName":null,"beat":"","setting":"","camera":"","prompt":"She kneels and places the cup, wrapped mirror, and smooth key in a row. She looks at them as if they belong to someone she used to know. Then she gets up and follows the hum.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"bible-g-087","variant":"bible_girl","source":"bible-g","n":87,"seq":87,"total":114,"start":1290,"end":1305,"timecode":"21:30-21:45","track":null,"act":null,"actName":null,"beat":"","setting":"","camera":"","prompt":"The floor slopes down into a circular shaft lined with old plaster. She descends a narrow iron ladder, each rung giving a small metallic complaint. The light above shrinks to a dirty coin.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"bible-g-088","variant":"bible_girl","source":"bible-g","n":88,"seq":88,"total":114,"start":1305,"end":1320,"timecode":"21:45-22:00","track":null,"act":null,"actName":null,"beat":"","setting":"","camera":"","prompt":"At the bottom, a corridor of hospital-green tiles stretches toward a half-open door. She touches the wall; it is cold, flat, and unremarkable. She moves toward it without hurrying.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"bible-g-089","variant":"bible_girl","source":"bible-g","n":89,"seq":89,"total":114,"start":1320,"end":1335,"timecode":"22:00-22:15","track":null,"act":null,"actName":null,"beat":"","setting":"","camera":"","prompt":"The door opens onto an empty ward. Curtains stir though the windows are sealed. Beyond one curtain, a shape rises and falls with a shallow, mechanical rhythm.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"bible-g-090","variant":"bible_girl","source":"bible-g","n":90,"seq":90,"total":114,"start":1335,"end":1350,"timecode":"22:15-22:30","track":null,"act":null,"actName":null,"beat":"","setting":"","camera":"","prompt":"She pulls the curtain aside. A body lies beneath white sheets, face obscured by tubes and tape. The woman recoils, then steps close enough to see the hand resting on the blanket.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"bible-g-091","variant":"bible_girl","source":"bible-g","n":91,"seq":91,"total":114,"start":1350,"end":1365,"timecode":"22:30-22:45","track":null,"act":null,"actName":null,"beat":"","setting":"","camera":"","prompt":"She compares that hand to her own: same scar, same crooked nail, same tremor. She lays her palm beside it, not touching. The monitor's green line keeps crawling.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"bible-g-092","variant":"bible_girl","source":"bible-g","n":91,"seq":92,"total":114,"start":1350,"end":1365,"timecode":"22:30-22:45","track":null,"act":null,"actName":null,"beat":"","setting":"","camera":"","prompt":"The ward lights flicker. The walls ripple back into organic stone for a second, then settle. The woman backs toward the door, unsure whether she has reached an exit or another trick.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":"Source numbering anomaly: this entry is labelled 091 a second time in the PDF (the first 091 entry is the previous generation). Its true sequence position is 92."},{"id":"bible-g-093","variant":"bible_girl","source":"bible-g","n":92,"seq":93,"total":114,"start":1365,"end":1380,"timecode":"22:45-23:00","track":null,"act":null,"actName":null,"beat":"","setting":"","camera":"","prompt":"A small Figment crawls from beneath the bed: a knot of elbows, damp hair, and child-sized hands. It holds the cracked ceramic cup. The woman kneels rather than reaching for it.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"bible-g-094","variant":"bible_girl","source":"bible-g","n":93,"seq":94,"total":114,"start":1380,"end":1395,"timecode":"23:00-23:15","track":null,"act":null,"actName":null,"beat":"","setting":"","camera":"","prompt":"The Figment places the cup between her shoes. Its many hands uncurl, one by one. She recognizes the gesture from the forest creature and lets the silence stand.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"bible-g-095","variant":"bible_girl","source":"bible-g","n":94,"seq":95,"total":114,"start":1395,"end":1410,"timecode":"23:15-23:30","track":null,"act":null,"actName":null,"beat":"","setting":"","camera":"","prompt":"The creature's limbs soften into dark sludge threaded with violet light. The sludge seeps into the grout. No sting, no victory music, no reward-only a faint warmth in the floor.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"bible-g-096","variant":"bible_girl","source":"bible-g","n":95,"seq":96,"total":114,"start":1410,"end":1425,"timecode":"23:30-23:45","track":null,"act":null,"actName":null,"beat":"","setting":"","camera":"","prompt":"The monitor's rhythm stutters. The woman grips the bedrail until her fingers hurt. She looks at the covered face, then at the exit, caught between two ordinary acts.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"bible-g-097","variant":"bible_girl","source":"bible-g","n":96,"seq":97,"total":114,"start":1425,"end":1440,"timecode":"23:45-24:00","track":null,"act":null,"actName":null,"beat":"","setting":"","camera":"","prompt":"She pulls a chair beside the bed and sits. The chair squeals against the tile. She does not remove the tubes or shake the body; she simply stays, shoulders sagging.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"bible-g-098","variant":"bible_girl","source":"bible-g","n":97,"seq":98,"total":114,"start":1440,"end":1455,"timecode":"24:00-24:15","track":null,"act":null,"actName":null,"beat":"","setting":"","camera":"","prompt":"Time drags. A curtain taps the radiator. The woman rubs her thumb over the old scar on her hand. The monitor keeps its indifferent rhythm.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"bible-g-099","variant":"bible_girl","source":"bible-g","n":98,"seq":99,"total":114,"start":1455,"end":1470,"timecode":"24:15-24:30","track":null,"act":null,"actName":null,"beat":"","setting":"","camera":"","prompt":"The covered hand twitches once. She rises too quickly, knocks the chair over, and catches herself on the bedrail. Nothing else moves.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"bible-g-100","variant":"bible_girl","source":"bible-g","n":99,"seq":100,"total":114,"start":1470,"end":1485,"timecode":"24:30-24:45","track":null,"act":null,"actName":null,"beat":"","setting":"","camera":"","prompt":"She waits for a second twitch. None comes. Her breath shudders; she picks the chair up and sets it back where it was, carefully aligning its legs with the floor tiles.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"bible-g-101","variant":"bible_girl","source":"bible-g","n":100,"seq":101,"total":114,"start":1485,"end":1500,"timecode":"24:45-25:00","track":null,"act":null,"actName":null,"beat":"","setting":"","camera":"","prompt":"The ward stretches into an endless corridor. Doorways bloom along the walls, each showing a fragment of the places she crossed. She turns away from them and faces the far end.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"bible-g-102","variant":"bible_girl","source":"bible-g","n":101,"seq":102,"total":114,"start":1500,"end":1515,"timecode":"25:00-25:15","track":null,"act":null,"actName":null,"beat":"","setting":"","camera":"","prompt":"At the far end, a red exit sign hangs upside down. Its light pulses weakly. She walks toward it, dragging one foot, never looking back at the open doors.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"bible-g-103","variant":"bible_girl","source":"bible-g","n":102,"seq":103,"total":114,"start":1515,"end":1530,"timecode":"25:15-25:30","track":null,"act":null,"actName":null,"beat":"","setting":"","camera":"","prompt":"The corridor begins to fold. The ceiling lowers, floor rises, and the walls curl around her like a closing shell. She presses forward on hands and knees.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"bible-g-104","variant":"bible_girl","source":"bible-g","n":103,"seq":104,"total":114,"start":1530,"end":1545,"timecode":"25:30-25:45","track":null,"act":null,"actName":null,"beat":"","setting":"","camera":"","prompt":"She reaches the exit sign and finds no door, only a patch of bare wall with a small, dark seam. She runs her fingers along it until a splinter catches under her nail.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"bible-g-105","variant":"bible_girl","source":"bible-g","n":104,"seq":105,"total":114,"start":1545,"end":1560,"timecode":"25:45-26:00","track":null,"act":null,"actName":null,"beat":"","setting":"","camera":"","prompt":"She digs at the seam with the broken nail. The plaster crumbles. Behind it is not daylight but a narrow line of warm, living darkness, breathing softly.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"bible-g-106","variant":"bible_girl","source":"bible-g","n":105,"seq":106,"total":114,"start":1560,"end":1575,"timecode":"26:00-26:15","track":null,"act":null,"actName":null,"beat":"","setting":"","camera":"","prompt":"She leans her forehead against the crack. A low human breath answers from the other side, not words. Her face tightens as if she recognizes the rhythm without knowing why.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"bible-g-107","variant":"bible_girl","source":"bible-g","n":106,"seq":107,"total":114,"start":1575,"end":1590,"timecode":"26:15-26:30","track":null,"act":null,"actName":null,"beat":"","setting":"","camera":"","prompt":"She widens the crack with both hands. The wall tears like wet paper, exposing a thin slit of pale light. The entire structure groans; distant towers begin to slump.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"bible-g-108","variant":"bible_girl","source":"bible-g","n":107,"seq":108,"total":114,"start":1590,"end":1605,"timecode":"26:30-26:45","track":null,"act":null,"actName":null,"beat":"","setting":"","camera":"","prompt":"The checkerboard floor breaks into floating tiles. The woman falls to one knee and clutches the edge. Rather than leap, she tests the light with one trembling hand.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"bible-g-109","variant":"bible_girl","source":"bible-g","n":108,"seq":109,"total":114,"start":1605,"end":1620,"timecode":"26:45-27:00","track":null,"act":null,"actName":null,"beat":"","setting":"","camera":"","prompt":"Her hand passes through. For the first time, the light does not retreat. She closes her eyes, takes one painful breath, and pulls herself forward.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"bible-g-110","variant":"bible_girl","source":"bible-g","n":109,"seq":110,"total":114,"start":1620,"end":1635,"timecode":"27:00-27:15","track":null,"act":null,"actName":null,"beat":"","setting":"","camera":"","prompt":"Behind her, the cathedral, forest, desert, and hospital overlap in a collapsing panorama. Figments stand in distant doorways, not waving or pleading. They simply watch until their outlines blur.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"bible-g-111","variant":"bible_girl","source":"bible-g","n":110,"seq":111,"total":114,"start":1635,"end":1650,"timecode":"27:15-27:30","track":null,"act":null,"actName":null,"beat":"","setting":"","camera":"","prompt":"She crawls through the slit. Her coat catches on the wall; she leaves a long strip behind. The light fills the frame, dirty white with visible film grain, not a clean digital glow.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"bible-g-112","variant":"bible_girl","source":"bible-g","n":111,"seq":112,"total":114,"start":1650,"end":1665,"timecode":"27:30-27:45","track":null,"act":null,"actName":null,"beat":"","setting":"","camera":"","prompt":"Sound drops to near silence. A single inhale, a pause, then an exhale. The camera holds on the pale frame long enough for discomfort to set in.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"bible-g-113","variant":"bible_girl","source":"bible-g","n":112,"seq":113,"total":114,"start":1665,"end":1680,"timecode":"27:45-28:00","track":null,"act":null,"actName":null,"beat":"","setting":"","camera":"","prompt":"Cut to black. A fluorescent hum continues. After several seconds, a monitor beeps once, then returns to its uneven rhythm. No title card, no explanation.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"bible-g-114","variant":"bible_girl","source":"bible-g","n":113,"seq":114,"total":114,"start":1680,"end":1695,"timecode":"28:00-28:15","track":null,"act":null,"actName":null,"beat":"","setting":"","camera":"","prompt":"Final image: on a black field, the words FEVER DREAM appear in distressed ochre lettering, edges fraying like old film emulsion. One faint violet pulse travels through the letters, then dies. Final production critique checklist ● Does the woman's coat, injuries, carried objects, and fatigue persist from clip to clip? ● Does every Figment create a specific interaction rather than merely pose as a monster? ● Are there no more than one or two dominant visual ideas in any 15-second generation? ● Do cuts preserve screen direction, light direction, and the woman's physical position whenever possible? ● Is the final waking state deliberately unresolved, with no explanatory voice-over or tidy cure? ● If a generated clip looks too polished, too colorful, or too clean, regenerate it rather than accepting a break in the analog texture.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null}];
